'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
const d = () => { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; };

(async () => {
  // Old flight completing must not detach/overwrite a newer flight.
  {
    const gates = [d(), d(), d()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick();
    c.invalidate('k');
    const b = c.get('k'); await tick();
    gates[0].resolve('old'); assert.equal(await a, 'old');
    const b2 = c.get('k'); // must join flight b
    assert.equal(calls, 2);
    gates[1].resolve('new');
    assert.equal(await b, 'new'); assert.equal(await b2, 'new');
    assert.equal(await c.get('k'), 'new'); assert.equal(calls, 2);
  }
  // set wins; old completion doesn't restart TTL; expiry starts a new load.
  {
    let t = 0; const g = d(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (++calls === 1 ? g.promise : 'L' + calls) });
    const a = c.get('k'); await tick();
    c.set('k', 'S');
    t = 5; g.resolve('old'); assert.equal(await a, 'old');
    assert.equal(await c.get('k'), 'S');
    t = 10; assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'L2');
  }
  // set expires while old load pending -> new load, not detached one.
  {
    let t = 0; const g = d(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (++calls === 1 ? g.promise : 'L' + calls) });
    c.get('k'); await tick(); c.set('k', 'S'); t = 10;
    assert.equal(await c.get('k'), 'L2');
  }
  // Rejections not cached; shared reason; sync throw; non-Error reason.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, load: () => { calls++; if (calls === 1) throw 'boom'; if (calls === 2) return Promise.reject(null); return 'ok'; } });
    const [r1, r2] = await Promise.allSettled([c.get('k'), c.get('k')]);
    assert.equal(r1.reason, 'boom'); assert.equal(r2.reason, 'boom'); assert.equal(calls, 1);
    await assert.rejects(c.get('k'), r => r === null);
    assert.equal(await c.get('k'), 'ok'); assert.equal(calls, 3);
  }
  // Detached rejected flight does not drop the newer flight.
  {
    const gates = [d(), d()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick();
    gates[0].reject(new Error('x')); await assert.rejects(a);
    c.get('k'); assert.equal(calls, 2);
    gates[1].resolve('v'); assert.equal(await b, 'v');
  }
  // Repeated invalidations with no value are separate barriers; clear too.
  {
    const gates = [d(), d(), d(), d()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    c.get('k'); await tick(); c.invalidate('k');
    c.get('k'); await tick(); c.invalidate('k');
    const p3 = c.get('k'); await tick(); c.clear();
    const p4 = c.get('k'); await tick();
    assert.equal(calls, 4);
    gates[0].resolve(1); gates[1].resolve(2); gates[2].resolve(3); await p3;
    gates[3].resolve(4); assert.equal(await p4, 4);
    assert.equal(await c.get('k'), 4); assert.equal(calls, 4);
  }
  // load mutating synchronously; load reading own key joins flight.
  {
    let calls = 0, inner;
    const c = createCache({ now: () => 0, load(k) { calls++; if (calls === 1) { inner = c.get(k); c.set(k, 'S'); } return 'L' + calls; } });
    assert.equal(await c.get('k'), 'L1'); assert.equal(await inner, 'L1');
    assert.equal(await c.get('k'), 'S'); assert.equal(calls, 1);
  }
  // ttl 0: dedupes in flight, never reuses settled.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, ttlMs: 0, load: async () => ++calls });
    assert.deepEqual(await Promise.all([c.get('k'), c.get('k')]), [1, 1]);
    assert.equal(await c.get('k'), 2); assert.equal(c.size, 0);
  }
  console.log('all scratch checks passed');
})().catch(e => { console.error(e); process.exit(1); });

